class Solution {
public:
    int maximumBeauty(vector<int>& flowers) {
        int n = flowers.size();
        vector<int> pos_pref(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            pos_pref[i + 1] = pos_pref[i] + max(0, flowers[i]);
        }

        unordered_map<int, int> first;
        int ans = -2e9;
        for (int i = 0; i < n; ++i) {
            int f = flowers[i];
            if (first.count(f)) {
                int start = first[f];
                int internal_pos = pos_pref[i] - pos_pref[start + 1];
                ans = max(ans, 2 * f + internal_pos);
