import java.util.*;

class Solution {
    public int maximumBeauty(int[] flowers) {
        int n = flowers.length;
        int[] posPref = new int[n + 1];
        for (int i = 0; i < n; ++i) {
            posPref[i + 1] = posPref[i] + Math.max(0, flowers[i]);
        }

        Map<Integer, Integer> first = new HashMap<>();
        int ans = Integer.MIN_VALUE;
        for (int i = 0; i < n; ++i) {
            int f = flowers[i];
            if (first.containsKey(f)) {
                int start = first.get(f);
                int internalPos = posPref[i] - posPref[start + 1];
                ans = Math.max(ans, 2 * f + internalPos);
            } else {
                first.put(f, i);
            }
        }
        return ans;
    }
}

