var maximumBeauty = function(flowers) {
    const n = flowers.length;
    const posPref = Array(n + 1).fill(0);
    for (let i = 0; i < n; ++i) {
        posPref[i + 1] = posPref[i] + Math.max(0, flowers[i]);
    }

    const first = new Map();
    let ans = -Infinity;
    for (let i = 0; i < n; ++i) {
        const f = flowers[i];
        if (first.has(f)) {
            const start = first.get(f);
            const internalPos = posPref[i] - posPref[start + 1];
            ans = Math.max(ans, 2 * f + internalPos);
        } else {
            first.set(f, i);
        }
    }
    return ans;
};
